mapper.select:
select count(id)
from sys_user
where id_card_hash = #{idCardHash}

select count(id)
from sys_register_application
where id_card_hash = #{idCardHash}

select count(id)
from sys_organization
where unified_social_credit_code = #{creditCode}

select count(id)
from sys_register_application
where unified_social_credit_code = #{creditCode}

select count(id)
from sys_register_application
where phone = #{phone}

select id, type, name, phone, unified_social_credit_code, legal_person_name, business_license_attachment_id, verify_status, verify_remark, verify_user, verify_time, create_time, update_time, create_user, update_user from sys_register_application
and type = #{request.type}
and verify_status = #{request.verifyStatus}
and (name like concat('%', #{request.keyword}, '%') or phone like concat('%', #{request.keyword}, '%'))
order by create_time desc
